 async Task<IActionResult> Form(string p,string view,CancellationToken c){if(!await Allowed(p,c))return Forbid();ViewBag.Veiculos=await s.VeiculosAsync(T(),E(),new(Status:"ATIVO"),c);ViewBag.Motoristas=await s.MotoristasAsync(T(),E(),new(Status:"ATIVO"),c);return View(view);}async Task<IActionResult> ViewIf<T>(string p,Task<T> model,string view,CancellationToken c)=>await Allowed(p,c)?View(view,await model):Forbid();async Task<IActionResult> Write<T>(string p,Func<Task<T>> op,string redirect,string view,object model,CancellationToken c){if(!await Allowed(p,c))return Forbid();try{await op();return Redirect(redirect);}catch(Exception x)when(x is ArgumentException or InvalidOperationException or KeyNotFoundException){ModelState.AddModelError("",x.Message);return View(view,model);}}async Task<bool> Allowed(string p,CancellationToken c){var i=p.LastIndexOf('.');return(await auth.EvaluateAsync(new(U(),"frotas",p[..i],p[(i+1)..],T(),E(),tenant.ExercicioId,null,null,Trace(),"WEB_FUNC04"),c)).Permitido;}long T()=>tenant.TenantId??throw new InvalidOperationException("tenant_id obrigatório.");long E()=>tenant.EntidadeId??throw new InvalidOperationException("entidade_id obrigatório.");long U()=>user.UsuarioId??throw new InvalidOperationException("Usuário obrigatório.");string Trace()=>HttpContext.TraceIdentifier;
